#!/usr/bin/env python3
"""Build every generated file of this extension from the pinned sources.

Inputs: the Discovery document of the YouTube Analytics API v2 pinned in this folder
(youtubeAnalytics_v2.json), channel_reports.json (the report tables of YouTube's
channel reports page, extract_channel_reports.py), names.py (titles, summaries,
areas), step_ids.json (frozen step ids) and composite_specs.py (the everyday steps).
Outputs: runtime/registry.json, the four contract files, ui/actions/actions.yaml, the
YouTube Analytics API and Coverage pages, and extension.yaml. Run from the bundle root:

    python3 tests/reference/build_contracts.py

tests/test_contracts.py fails when a committed file differs from what this script
renders, so the files never drift from the sources.

A step id is written once to step_ids.json (``--new-ids`` adds ids for methods that
have none) and never derived again: titles may change, ids may not.
"""

from __future__ import annotations

import hashlib
import json
import re
import sys
from pathlib import Path
from typing import Any

import yaml

