# -- sources -------------------------------------------------------------------------------


def snake(text: str) -> str:
    text = re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", text)
    text = re.sub(r"[^A-Za-z0-9]+", "_", text)
    return text.strip("_").lower()


def document(api: str = "analytics") -> dict[str, Any]:
    """The pinned Discovery document; refused when its bytes are not the pinned ones."""
    pin = SOURCES[api]
    raw = (HERE / pin["file"]).read_bytes()
    digest = hashlib.sha256(raw).hexdigest()
    if digest != pin["sha256"] or len(raw) != pin["bytes"]:
        raise SystemExit(f"{pin['file']} is not the pinned document (SHA-256 {digest})")
    return json.loads(raw)


def methods(api: str = "analytics") -> list[dict[str, Any]]:
    """Every method of the document, depth first, as the document lists them."""
    out: list[dict[str, Any]] = []

    def walk(resources: dict[str, Any]) -> None:
        for resource in resources.values():
            out.extend(resource.get("methods", {}).values())
            walk(resource.get("resources", {}))

    walk(document(api)["resources"])
    return out


def all_methods() -> list[tuple[str, dict[str, Any]]]:
    return [(api, m) for api in SOURCES for m in methods(api)]


def channel_reports() -> dict[str, Any]:
    return json.loads(CHANNEL_REPORTS.read_text(encoding="utf-8"))


def step_ids() -> dict[str, str]:
    return json.loads(STEP_IDS.read_text(encoding="utf-8")) if STEP_IDS.exists() else {}


def new_step_id(title: str) -> str:
    words = [w for w in snake(title.replace("'s", "")).split("_") if w not in {"a", "an", "the"}]
    return "_".join(words)


def resource_of(method_id: str) -> str:
    return method_id.split(".")[1]


def area_of(method_id: str) -> str:
    resource = resource_of(method_id)
    for area, resources in names.AREAS.items():
        if resource in resources:
            return area
    raise SystemExit(f"{method_id} has no area")


# -- text ----------------------------------------------------------------------------------


def clean(text: str) -> str:
    """Source text without markdown, links and doc-only remarks."""
    text = re.sub(r"\[([^\]]+)\]\([^)]+\)", r"\1", text)
    text = text.replace("**", "").replace("`", "").replace("*", "")
    # The Analytics document ends some descriptions with remarks for its own tooling.
    text = re.split(r"[\"']?,?\s*\b(?:required|pattern|minValue):", text)[0]
    text = " ".join(text.split())
    text = re.sub(r"\s+([.,;:])", r"\1", text)
    text = re.sub(r"[\"',\s]+$", "", text).strip()
    return text


def sentences(text: str, limit: int) -> str:
    text = clean(text)
    out = ""
    for part in re.split(r"(?<=[.!?])\s+", text):
        if not part:
            continue
        candidate = f"{out} {part}".strip()
        if len(candidate) > limit:
            break
        out = candidate
    if not out and text:
        out = text[: limit - 1].rstrip() + "…"
    return out


def short_scope(scope: str) -> str:
    return scope[len(SCOPE) :] if scope.startswith(SCOPE) else scope


# -- parameters ----------------------------------------------------------------------------


def param_required(prm: dict[str, Any]) -> bool:
    """Required by the document's flag; the Analytics document says it in the text."""
    if prm.get("required"):
        return True
    return "required: true" in (prm.get("description") or "")


def node(name: str, prm: dict[str, Any]) -> dict[str, Any]:
    """How one parameter value is checked and sent (see runtime/params.py)."""
    kind = prm.get("type") or "string"
    out: dict[str, Any] = {"required": param_required(prm)}
    description = prm.get("description") or ""
    if prm.get("repeated"):
        out["kind"] = "text_list"
        out["max_items"] = 100
        out["item_max_length"] = 2000
        if prm.get("enum"):
            out["allowed"] = [str(v) for v in prm["enum"]]
        return out
    if kind == "integer":
        out["kind"] = "integer"
        for bound in ("minimum", "maximum"):
            if bound in prm:
                out[bound] = int(prm[bound])
        match = re.search(r"minValue: (\d+)", description)
        if "minimum" not in out and match:
            out["minimum"] = int(match.group(1))
    elif kind == "boolean":
        out["kind"] = "boolean"
    else:
        out["kind"] = "text"
        out["max_length"] = 2000
        if prm.get("enum"):
            out["allowed"] = [str(v) for v in prm["enum"]]
        if prm.get("format") == "google-datetime":
            out["format"] = "date-time"
        elif "YYYY-MM-DD" in description:
            out["format"] = "date"
    return out


def pager_of(method_id: str, m: dict[str, Any], doc: dict[str, Any]) -> dict[str, Any] | None:
    params = m.get("parameters", {})
    if "pageToken" not in params:
        return None
    response = doc["schemas"].get(m.get("response", {}).get("$ref", ""), {})
    props = response.get("properties", {})
    if "nextPageToken" not in props or "items" not in props:
        raise SystemExit(f"{method_id} takes pageToken but answers no nextPageToken and items")
    size = params.get("maxResults")
    if size is None:
        return {
            "token": "pageToken",
            "token_input": "page_token",
            "size": None,
            "size_input": None,
            "max": None,
            "min": 1,
        }
    raise SystemExit(f"{method_id}: a page size is not handled")  # pragma: no cover


def answer_of(m: dict[str, Any]) -> str:
    if m.get("supportsMediaUpload") or m.get("supportsMediaDownload"):
        raise SystemExit(f"{m['id']}: media is not handled")
    return "json" if m.get("response") else "none"


def describe(method_id: str, entry: dict[str, Any], source_text: str) -> str:
    summary = names.TITLES[method_id][1]
    notes: list[str] = [summary]
    detail = sentences(source_text, 300)
    if detail and detail.rstrip(".") not in summary:
        notes.append(f"YouTube: {detail}")
    notes.append(
        f"Calls {method_id} ({entry['method']} {entry['path']}) of the YouTube Analytics API."
    )
    if entry["pager"]:
        notes.append(
            "Returns one page in items with next_page_token; with all_pages it reads every "
            "page, up to max_items."
        )
    if method_id == "youtubeAnalytics.reports.query":
        notes.append(
            "Sent as given: Get channel report, Get video report and Get top videos check the "
            "combination against YouTube's report tables first."
        )
    notes.append("Google scopes: " + ", ".join(short_scope(s) for s in entry["scopes"]) + ".")
    return " ".join(notes)


# -- the registry --------------------------------------------------------------------------


def registry_entry(api: str, m: dict[str, Any], ids: dict[str, str]) -> dict[str, Any]:
    doc = document(api)
    method_id = m["id"]
    path_params: list[dict[str, Any]] = []
    query: list[dict[str, Any]] = []
    for name, prm in m.get("parameters", {}).items():
        if prm["location"] == "path":  # pragma: no cover - the document has none
            path_params.append(
                {
                    "name": name,
                    "input": snake(name),
                    "node": {"required": True, "kind": "text", "max_length": 500},
                }
            )
        elif prm["location"] == "query":
            description = clean(prm.get("description") or "") or name
            if prm.get("deprecated"):
                description = (description + " Deprecated in the source.").strip()
            query.append(
                {
                    "name": name,
                    "input": snake(name),
                    "node": node(name, prm),
                    "description": description,
                }
            )
        else:
            raise SystemExit(f"{method_id}: parameter in {prm['location']!r} is not handled")
    request = m.get("request", {}).get("$ref")
    body = None
    if request:
        body = {
            "required": True,
            "json": {
                "schema": request,
                "properties": sorted(doc["schemas"][request].get("properties", {})),
            },
        }
    kind = "read" if m["httpMethod"] == "GET" else "write"
    entry: dict[str, Any] = {
        "title": names.TITLES[method_id][0],
        "method": m["httpMethod"],
        "path": "/" + m["path"],
        "api": api,
        "vendor_method_id": method_id,
        "resource": resource_of(method_id),
        "area": area_of(method_id),
        "kind": kind,
        "scopes": sorted(m.get("scopes", [])),
        "answer": answer_of(m),
        # QueryResponse.errors: "When set, indicates that the operation failed."; the
        # group answers carry the same Errors object ("The presence of an error field
        # signals that the operation has failed").
        "fails_with_errors": (m.get("response") or {}).get("$ref") in ERRORS_ANSWERS,
        "exactly_one": EXACTLY_ONE.get(method_id, []),
        "path_params": path_params,
        "query": query,
        "body": body,
        "pager": pager_of(method_id, m, doc),
    }
    if kind == "write":
        entry["processing"] = {"accepted_always": False, "check": None}
    entry["description"] = describe(method_id, entry, m.get("description") or "")
    used = [p["input"] for p in path_params + query]
    if len(set(used)) != len(used) or set(used) & RESERVED_INPUTS:
        raise SystemExit(f"{method_id}: input names collide: {used}")
    _ = ids
    return entry


def ordered(ids: dict[str, str]) -> list[tuple[str, str, dict[str, Any]]]:
    """Areas in order, resources in order; reads first, deletions last within a resource."""
    weight = {"GET": 0, "POST": 1, "PUT": 2, "PATCH": 3, "DELETE": 4}
    resources = [r for rs in names.AREAS.values() for r in rs]
    rows = []
    for index, (api, m) in enumerate(all_methods()):
        if m["id"] in names.EXCLUDED:
            continue
        rows.append(
            (
                list(names.AREAS).index(area_of(m["id"])),
                resources.index(resource_of(m["id"])),
                weight[m["httpMethod"]],
                index,
                api,
                m,
            )
        )
    rows.sort(key=lambda r: r[:4])
    return [(ids[r[5]["id"]], r[4], r[5]) for r in rows]


def sources_facts() -> dict[str, Any]:
    out = {}
    for api, pin in SOURCES.items():
        doc = document(api)
        out[api] = {
            "url": pin["url"],
            "sha256": pin["sha256"],
            "bytes": pin["bytes"],
            "downloaded": pin["downloaded"],
            "name": doc["name"],
            "version": doc["version"],
            "revision": doc["revision"],
            "root_url": doc["rootUrl"],
        }
    return out


#: What the runtime keeps of each report table (runtime/reports.py).
REPORT_KEYS = (
    "id",
    "dimensions",
    "metrics",
    "monetary_metrics",
    "filters",
    "fixed_filters",
    "sort_options",
    "max_results",
    "sort_required",
    "monetary_scope_required",
)


def build_registry(ids: dict[str, str]) -> dict[str, Any]:
    operations = {sid: registry_entry(api, m, ids) for sid, api, m in ordered(ids)}
    tables = channel_reports()
    return {
        "sources": sources_facts(),
        "channel_reports_source": tables["source"],
        "channel_reports": [{k: r[k] for k in REPORT_KEYS} for r in tables["reports"]],
        "revenue_connection_types": REVENUE_TYPES,
        "excluded": dict(sorted(names.EXCLUDED.items())),
        "operations": operations,
    }


# -- contract rows -------------------------------------------------------------------------


def value_type(schema: dict[str, Any]) -> str:
    kind = schema.get("type")
    if isinstance(kind, list):
        kinds = [k for k in kind if k != "null"]
        if len(kinds) != 1:
            return "text"
        kind = kinds[0]
    return {"integer": "integer", "boolean": "boolean", "array": "array", "object": "object"}.get(
        str(kind), "text"
    )


def node_schema(n: dict[str, Any], *, title: str, description: str) -> dict[str, Any]:
    kind = n["kind"]
    schema: dict[str, Any]
    if kind == "integer":
        schema = {"type": "integer", **{k: n[k] for k in ("minimum", "maximum") if k in n}}
    elif kind == "boolean":
        schema = {"type": "boolean"}
    elif kind == "text_list":
        items: dict[str, Any] = {"type": "string", "maxLength": n["item_max_length"]}
        if n.get("allowed"):
            items = {"type": "string", "enum": n["allowed"]}
        schema = {"type": "array", "items": items, "maxItems": n["max_items"]}
    else:
        schema = {"type": "string", "maxLength": n["max_length"]}
        if n.get("allowed"):
            schema["enum"] = n["allowed"]
        if n.get("format") == "date":
            schema["pattern"] = r"^\d{4}-\d{2}-\d{2}$"
    schema["title"] = title
    if description:
        schema["description"] = description
    return schema


def widget_for(n: dict[str, Any]) -> str:
    kind = n["kind"]
    if kind == "integer":
        return "integer"
    if kind == "boolean":
        return "boolean"
    if kind == "text_list":
        return "multi_select" if n.get("allowed") else "json"
    if n.get("allowed"):
        return "select"
    return "text"


def step_inputs(entry: dict[str, Any]) -> list[dict[str, Any]]:
    """Every input of a generated step: (name, required, schema, widget, help)."""
    rows: list[dict[str, Any]] = []
    for prm in entry["path_params"]:
        rows.append(
            {
                "name": prm["input"],
                "required": True,
                "schema": node_schema(
                    prm["node"], title=prm["name"], description=f"The {prm['name']} in the path."
                ),
                "widget": "text",
            }
        )
    for prm in entry["query"]:
        n = prm["node"]
        rows.append(
            {
                "name": prm["input"],
                "required": bool(n["required"]),
                "schema": node_schema(n, title=prm["name"], description=prm["description"][:400]),
                "widget": widget_for(n),
                "options": n.get("allowed"),
            }
        )
    pager = entry["pager"]
    if pager:
        rows.append(
            {
                "name": "all_pages",
                "required": False,
                "schema": {
                    "type": "boolean",
                    "title": "All pages",
                    "description": (
                        "Read page after page until the list ends, max_items are read, the "
                        "output is full or time runs out; then next_page_token says where to "
                        "continue."
                    ),
                },
                "widget": "boolean",
            }
        )
        rows.append(
            {
                "name": "max_items",
                "required": False,
                "schema": {
                    "type": "integer",
                    "minimum": 1,
                    "maximum": 100000,
                    "title": "Most records",
                    "description": "With all_pages: the most records to read (default 10000).",
                },
                "widget": "integer",
            }
        )
        rows.append(
            {
                "name": "skip",
                "required": False,
                "schema": {
                    "type": "integer",
                    "minimum": 0,
                    "maximum": 100000,
                    "title": "Skip",
                    "description": (
                        "With all_pages and page_token: how many records of that page an "
                        "earlier run already returned (its next_skip)."
                    ),
                },
                "widget": "integer",
            }
        )
    body = entry["body"]
    if body:
        shape = body["json"]
        rows.append(
            {
                "name": "body",
                "required": body["required"],
                "schema": {
                    "type": "object",
                    "additionalProperties": True,
                    "title": "Request body",
                    "description": (
                        f"The {shape['schema']} resource as JSON. Fields: "
                        + ", ".join(shape["properties"])
                        + "."
                    )[:400],
                },
                "widget": "json",
            }
        )
    return rows


def generic_outputs(entry: dict[str, Any]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = [
        {
            "name": "status",
            "type": ["integer", "null"],
            "description": "YouTube's HTTP status (none in a test run).",
        }
    ]
    rows.append(
        {
            "name": "data",
            "type": ["object", "array", "string", "number", "boolean", "null"],
            "description": (
                "What YouTube returned (JSON); for a list, the answer without items."
                if entry["pager"]
                else "What YouTube returned (JSON)."
            ),
        }
    )
    if entry["pager"]:
        rows += composite_specs.PAGE_OUTPUTS
    if entry["kind"] == "write":
        rows += PROCESSING_OUTPUTS
    rows += [
        {
            "name": "etag",
            "type": ["string", "null"],
            "description": "The ETag header, when YouTube sends one.",
        },
        WARNINGS_OUTPUT,
    ]
    if entry["kind"] == "write":
        rows += [
            {"name": "external_effect_status", "type": "string"},
            {"name": "definitely_no_external_effect", "type": "boolean"},
        ]
    return rows


def output_row(row: dict[str, Any]) -> dict[str, Any]:
    schema = {k: v for k, v in row.items() if k not in {"name", "value_type"}}
    vt = row.get("value_type") or value_type(schema)
    if row["name"] == "data":
        vt = "object"
        schema["additionalProperties"] = True
    return {"name": row["name"], "value_type": vt, "schema": schema}


def composite_input_rows(spec: dict[str, Any]) -> list[dict[str, Any]]:
    rows = []
    for item in spec["inputs"]:
        schema = {k: v for k, v in item.items() if k not in {"name", "required", "value_type"}}
        widget = "text"
        if item.get("value_type") == "artifact_handle":
            widget = "artifact_picker"
        elif item.get("type") == "integer":
            widget = "integer"
        elif item.get("type") == "boolean":
            widget = "boolean"
        elif item.get("type") == "array":
            widget = "multi_select" if item["items"].get("enum") else "json"
        elif item.get("enum"):
            widget = "select"
        elif item.get("multiline"):
            widget = "textarea"
            schema.pop("multiline")
        row = {
            "name": item["name"],
            "required": bool(item.get("required")),
            "schema": schema,
            "widget": widget,
            "options": item.get("enum") or item.get("items", {}).get("enum"),
        }
        if item.get("value_type"):
            row["value_type"] = item["value_type"]
        rows.append(row)
    return rows


def manifest_rows(registry: dict[str, Any]) -> list[dict[str, Any]]:
    """One row per step in step order: id, title, description, kind, inputs, outputs."""
    rows: list[dict[str, Any]] = []
    for spec in composite_specs.COMPOSITES:
        rows.append(
            {
                "id": spec["operation_id"],
                "title": spec["title"],
                "description": spec["description"],
                "kind": spec["kind"],
                "inputs": composite_input_rows(spec),
                "outputs": spec["outputs"],
                "area": "Everyday",
                "calls": spec["calls"],
                "file": COMPOSITE_FILES.get(spec["operation_id"]),
            }
        )
    for sid, entry in registry["operations"].items():
        rows.append(
            {
                "id": sid,
                "title": entry["title"],
                "description": entry["description"],
                "kind": entry["kind"],
                "inputs": step_inputs(entry),
                "outputs": generic_outputs(entry),
                "area": entry["area"],
                "calls": [f"{entry['method']} {entry['path']}"],
                "file": None,
            }
        )
    return rows


def operation_manifest(rows: list[dict[str, Any]]) -> dict[str, Any]:
    ops = []
    for row in rows:
        write = row["kind"] == "write"
        inputs = [{"name": "connection_ref", "value_type": "connection_ref", "required": True}]
        for item in row["inputs"]:
            vt = item.get("value_type") or value_type(item["schema"])
            inputs.append(
                {
                    "name": item["name"],
                    "value_type": vt,
                    "required": item["required"],
                    "schema": item["schema"],
                }
            )
        op: dict[str, Any] = {
            "operation_id": row["id"],
            "display_name": row["title"],
            "description": row["description"],
            "operation_kind": "action" if write else "source",
            "category": "marketing",
            "connection_type_ids": list(CONNECTION_TYPES),
            "workflow_visible": True,
        }
        if write:
            op["effect_kind"] = f"youtube_analytics_{row['id']}"
        outputs = [output_row(o) for o in row["outputs"]]
        op.update(
            {
                "inputs": inputs,
                "outputs": outputs,
                "result_fields": [f"result.{o['name']}" for o in outputs],
                "error_codes": ERROR_CODES_WRITE if write else ERROR_CODES_READ,
            }
        )
        ops.append(op)
    return {"operations": ops}


def step_ui_manifest(rows: list[dict[str, Any]]) -> dict[str, Any]:
    forms = []
    for row in rows:
        fields = []
        for item in row["inputs"]:
            label, help_text = field_texts.text_of(item["name"], item["schema"].get("description"))
            field: dict[str, Any] = {
                "name": item["name"],
                "label": label,
                "widget_type": item["widget"],
                "required": item["required"],
                "help_text": help_text[:400],
            }
            if item.get("options"):
                field["options"] = [{"label": v, "value": v} for v in item["options"]]
            if item["widget"] == "json":
                field["placeholder"] = "[]" if item["schema"].get("type") == "array" else "{}"
            fields.append(field)
        forms.append({"operation_id": row["id"], "title": row["title"], "fields": fields})
    return {"forms": forms}


def actions_manifest(rows: list[dict[str, Any]]) -> dict[str, Any]:
    actions = []
    for row in rows:
        write = row["kind"] == "write"
        action: dict[str, Any] = {
            "action_id": row["id"],
            "title": row["title"],
            "description": row["description"],
            "required_scopes": ["extension:invoke"],
            "handler": {"mode": "extension"},
        }
        if write:
            action["command_type"] = "invoke_extension_action"
        action.update(
            {
                "mutates_platform": write,
                "workflow_visible": True,
                "parameters": [
                    {"name": "connection_ref", "type": "connection_ref", "required": True}
                ]
                + [
                    {
                        "name": i["name"],
                        "type": "artifact_handle"
                        if i.get("value_type") == "artifact_handle"
                        else value_type(i["schema"])
                        if value_type(i["schema"]) != "text"
                        else "string",
                        "required": i["required"],
                    }
                    for i in row["inputs"]
                ],
                "result_fields": [o["name"] for o in row["outputs"]],
                "error_codes": ERROR_CODES_WRITE if write else ERROR_CODES_READ,
            }
        )
        actions.append(action)
    actions.append(
        {
            "action_id": "verify_identity",
            "title": "Verify YouTube channel",
            "description": (
                "Run by Flow Steward after a new authorization: reads the channel of the "
                "connected Google account (GET /youtube/v3/channels, mine) and returns its id "
                "and title."
            ),
            "required_scopes": ["extension:invoke"],
            "handler": {"mode": "extension"},
            "mutates_platform": False,
            "workflow_visible": False,
            "parameters": [],
        }
    )
    return {"actions": actions}


def artifact_policies(rows: list[dict[str, Any]]) -> dict[str, Any]:
    policies = []
    for row in rows:
        if row.get("file"):
            policies.append(
                {
                    "operation_id": row["id"],
                    "outputs": [
                        {
                            "kind": "artifact",
                            "value_type": "artifact_handle",
                            "binding_key": DOWNLOAD_BINDING,
                            "filename": row["file"]["filename"],
                            "content_type": row["file"]["content_type"],
                            "max_size_bytes": MAX_DOWNLOAD_BYTES,
                            "retention_class": "run_window",
                        }
                    ],
                }
            )
    return {"artifact_policies": policies}


def connection_types() -> dict[str, Any]:
    rows = []
    for type_id, facts in CONNECTION_TYPES.items():
        rows.append(
            {
                "connection_type_id": type_id,
                "display_name": facts["display_name"],
                "description": facts["description"],
                "auth": {
                    "type": "oauth2",
                    "provider_id": "google_youtube",
                    "scopes": {"required": [SCOPE + s for s in facts["scopes"]], "optional": []},
                },
                "capabilities": {"test_connection": True},
            }
        )
    return {"connection_types": rows}


