# -- UI pages ------------------------------------------------------------------------------

PAGE_IDS = {
    "Reports": "youtube-analytics-api-reports",
    "Groups": "youtube-analytics-api-groups",
}


def step_text(row: dict[str, Any]) -> str:
    kind = "changes data in YouTube Analytics" if row["kind"] == "write" else "reads only"
    calls = ", ".join(f"`{c}`" for c in row["calls"])
    inputs = [f"`{i['name']}`" + (" (required)" if i["required"] else "") for i in row["inputs"]]
    lines = [
        f"### {row['title']}",
        "",
        row["description"],
        "",
        f"Action id `{row['id']}` · {kind} · YouTube: {calls}",
        "",
        "Inputs: " + (", ".join(inputs) if inputs else "none") + ".",
        "",
    ]
    if row["area"] == "Everyday":
        outputs = ", ".join(
            f"`{o['name']}`"
            for o in row["outputs"]
            if o["name"] not in {"external_effect_status", "definitely_no_external_effect"}
        )
        lines += ["Results: " + outputs + ".", ""]
    return "\n".join(lines)


def api_pages(rows: list[dict[str, Any]]) -> dict[str, dict[str, Any]]:
    pages: dict[str, dict[str, Any]] = {}
    total = len(rows)
    counts = {area: sum(1 for r in rows if r["area"] == area) for area in PAGE_IDS}
    overview = "\n".join(
        [
            "The steps call the YouTube Analytics API v2 for the connected channel. Every "
            f"method of the API has a step: {total} steps in all, the everyday ones first.",
            "",
            "- **Checked combinations.** YouTube answers a report query it does not support "
            "with HTTP 400. Get channel report, Get video report and Get top videos first "
            "check the dimensions, metrics, filters, sort and max_results against the report "
            "tables of YouTube's channel reports page (see Report tables) and refuse a "
            "combination no table allows, with the reason. `matched_reports` names the "
            "tables that allow the request.",
            "- **Scopes.** Each step names the Google scopes that allow it. The connection "
            "type decides which scopes are asked for: YouTube channel analytics "
            "(yt-analytics.readonly) or YouTube channel analytics with revenue (also "
            "yt-analytics-monetary.readonly). Revenue metrics and ad performance reports "
            "need the second; the channel must be in the YouTube Partner Program.",
            "- **Numbers.** Report values are exact decimals, never rounded through floating "
            "point.",
            "- **Quota.** The YouTube Analytics API does not report a quota in its answers; "
            "when a limit is reached YouTube refuses and the step says so.",
            "- **Results.** A generated step returns `status`, `data` (YouTube's JSON), `etag` "
            "and `warnings`; Get analytics groups also returns `items`, `count`, `complete` "
            "and `next_page_token`.",
            "- **Lists.** With `all_pages` a list step reads page after page and never returns "
            "more than asked for; when it stops early, `next_page_token` and `next_skip` are "
            "where the next run starts (`page_token` and `skip`), so nothing is skipped or "
            "read twice.",
            "- **Request bodies** are the YouTube resource as JSON in `body`. A field the "
            "resource does not have is refused before sending.",
            "- **Changes are sent once.** A step that changes data is never retried "
            "automatically; when its outcome is unclear it says so, and you check YouTube "
            "before running it again. Test runs never send changes.",
            "",
            "The steps by area:",
            "",
            *[f"- **{area}** ({counts[area]} steps)" for area in PAGE_IDS],
        ]
    )
    everyday = "\n".join(step_text(r) for r in rows if r["area"] == "Everyday")
    pages["ui/pages/youtube-analytics-api.yaml"] = {
        "page_id": "youtube-analytics-api",
        "title": "YouTube Analytics API",
        "description": "How the YouTube Analytics steps work, and the everyday steps.",
        "components": [
            {
                "component_id": "api_overview",
                "type": "markdown",
                "title": "How the steps work",
                "body": overview + "\n",
            },
            {
                "component_id": "steps_everyday",
                "type": "markdown",
                "title": "Everyday",
                "body": everyday,
            },
        ],
    }
    for area, page_id in PAGE_IDS.items():
        area_rows = [r for r in rows if r["area"] == area]
        pages[f"ui/pages/{page_id}.yaml"] = {
            "page_id": page_id,
            "title": f"YouTube Analytics API: {area}",
            "description": f"The {len(area_rows)} {area.lower()} steps.",
            "components": [
                {
                    "component_id": "steps_" + snake(area),
                    "type": "markdown",
                    "title": area,
                    "body": "\n".join(step_text(r) for r in area_rows),
                }
            ],
        }
    return pages


def _groups_text(groups: list[dict[str, Any]]) -> str:
    if not groups:
        return "none"
    return "; ".join(f"{g['usage']}: {', '.join(g['values'])}" for g in groups)


def report_tables_page(registry: dict[str, Any]) -> dict[str, Any]:
    """The report tables the everyday report steps check against, as lists."""
    tables = channel_reports()
    source = tables["source"]
    blocks = [
        "The everyday report steps allow a combination when one of these tables of "
        f"YouTube's channel reports page ({source['url']}, updated "
        f"{source['last_updated']}) allows it. Metrics marked * need a connection with "
        "revenue access.",
        "",
    ]
    for report in tables["reports"]:
        monetary = set(report["monetary_metrics"])
        metrics = ", ".join(
            m + ("*" if m in monetary else "") for g in report["metrics"] for m in g["values"]
        )
        lines = [
            f"### {report['id']}",
            "",
            f"- Dimensions: {_groups_text(report['dimensions'])}",
            f"- Metrics: {metrics}",
            f"- Filters: {_groups_text(report['filters'])}",
        ]
        if report["fixed_filters"]:
            fixed = ", ".join(f"{k}=={v}" for k, v in report["fixed_filters"].items())
            lines.append(f"- Filter value: {fixed}")
        if report["max_results"] is not None:
            lines.append(f"- max_results: at most {report['max_results']}, required")
        if report["sort_required"]:
            lines.append("- sort: required")
        if report["sort_options"]:
            lines.append(f"- Sort options: {', '.join(report['sort_options'])}")
        if report["monetary_scope_required"]:
            lines.append("- Needs a connection with revenue access")
        blocks += lines + [""]
    _ = registry
    return {
        "page_id": "report-tables",
        "title": "Report tables",
        "description": "The dimension, metric and filter combinations YouTube allows.",
        "components": [
            {
                "component_id": "report_tables",
                "type": "markdown",
                "title": f"{len(tables['reports'])} channel reports",
                "body": "\n".join(blocks),
            }
        ],
    }


def coverage_page(registry: dict[str, Any]) -> dict[str, Any]:
    ops = list(registry["operations"].values())
    total = len(ops)
    reads = sum(1 for e in ops if e["kind"] == "read")
    source = registry["sources"]["analytics"]
    products = "\n".join(f"- **{name}**: {reason}" for name, reason in EXCLUDED_PRODUCTS.items())
    body = "\n".join(
        [
            f"The pinned Discovery document of the YouTube Analytics API v2 (revision "
            f"{source['revision']}, downloaded {source['downloaded']}) lists {total} methods. "
            f"**Each of them has its own step**: {reads} reads (GET) and {total - reads} "
            "changes to YouTube Analytics groups. Test runs never send changes.",
            "",
            f"The report tables of YouTube's channel reports page ("
            f"{len(registry['channel_reports'])} reports) are the rules the everyday report "
            "steps check a request against.",
            "",
            "Other YouTube APIs:",
            "",
            products,
            "",
            "The everyday steps on top: test the connection, get a channel report, get a "
            "video report, get the top videos of a period, get all my groups, create a group "
            "and add a video to a group.",
        ]
    )
    return {
        "page_id": "coverage",
        "title": "Coverage",
        "description": "What of the YouTube Analytics API the steps offer.",
        "components": [
            {
                "component_id": "coverage_summary",
                "type": "markdown",
                "title": "Coverage",
                "body": body + "\n",
            }
        ],
    }


def _resource_fields(api: str, ref: str | None) -> tuple[str, list[str], str | None, list[str]]:
    """The fields of a response schema, and for a list answer the fields of its items."""
    if not ref:
        return "", [], None, []
    schemas = document(api)["schemas"]
    top = schemas.get(ref, {}).get("properties", {})
    items = top.get("items", {})
    item_ref = (items.get("items") or {}).get("$ref") if items.get("type") == "array" else None
    item_fields = list(schemas.get(item_ref, {}).get("properties", {})) if item_ref else []
    return ref, list(top), item_ref, item_fields


def api_coverage_page(registry: dict[str, Any], rows: list[dict[str, Any]]) -> dict[str, Any]:
    """Every step: the YouTube Analytics method it calls, its inputs, the body fields it sends and the
    fields YouTube returns; then the methods without a step and why."""
    by_method = {m["id"]: (api, m) for api, m in all_methods()}
    by_id = {sid: e for sid, e in registry["operations"].items()}
    detail: list[str] = []
    for area in ["Everyday", *PAGE_IDS]:
        detail += [f"## {area}", ""]
        for row in (r for r in rows if r["area"] == area):
            inputs = [
                f"`{i['name']}`" + (" (required)" if i["required"] else "") for i in row["inputs"]
            ]
            detail += [f"### {row['title']} (`{row['id']}`)", ""]
            entry = by_id.get(row["id"])
            if entry is None:
                detail += ["YouTube: " + ", ".join(f"`{c}`" for c in row["calls"]) + ".", ""]
                detail += ["Inputs: " + (", ".join(inputs) or "none") + ".", ""]
                outputs = [
                    f"`{o['name']}`"
                    for o in row["outputs"]
                    if o["name"] not in {"external_effect_status", "definitely_no_external_effect"}
                ]
                detail += ["Returns: " + ", ".join(outputs) + ".", ""]
                continue
            cost = f", quota cost: {entry['quota']}" if entry.get("quota") else ""
            detail += [
                f"YouTube: `{entry['vendor_method_id']}` (`{entry['method']} {entry['path']}`)"
                f"{cost}.",
                "",
                "Inputs: " + (", ".join(inputs) or "none") + ".",
                "",
            ]
            body = (entry.get("body") or {}).get("json")
            if body:
                detail += [
                    f"Body (`body`, a {body['schema']}): "
                    + ", ".join(f"`{f}`" for f in body["properties"])
                    + ".",
                    "",
                ]
            if (entry.get("body") or {}).get("upload"):
                pass
            api, method = by_method[entry["vendor_method_id"]]
            ref, top, item_ref, item_fields = _resource_fields(
                api, (method.get("response") or {}).get("$ref")
            )
            if item_ref:
                detail += [
                    f"Returns a {ref}; each item of `items` is a {item_ref} with "
                    + ", ".join(f"`{f}`" for f in item_fields)
                    + ".",
                    "",
                ]
            elif ref:
                detail += [
                    f"Returns a {ref} with " + ", ".join(f"`{f}`" for f in top) + ".",
                    "",
                ]
            elif entry["answer"] == "file":
                detail += ["Returns the file as a workflow file in `file`.", ""]
            else:
                detail += ["YouTube answers without a body; the step returns its status.", ""]
    excluded = [f"- `{mid}`: {reason}" for mid, reason in registry["excluded"].items()]
    products = [f"- **{name}**: {reason}" for name, reason in EXCLUDED_PRODUCTS.items()]
    offered = [
        "Every method of the pinned Discovery document has its own step"
        + (", except these, for the reason given:" if excluded else "."),
        "",
        *excluded,
        "",
        "Other YouTube APIs:",
        "",
        *products,
    ]
    return {
        "page_id": "api-coverage",
        "title": "YouTube Analytics API coverage",
        "description": (
            "Every step, the YouTube Analytics method it calls, its inputs and what it returns, and "
            "what is deliberately not offered."
        ),
        "components": [
            coverage_page(registry)["components"][0],
            {
                "component_id": "coverage_detail",
                "type": "markdown",
                "title": "Every step",
                "body": "\n".join(detail) + "\n",
            },
            {
                "component_id": "coverage_not_offered",
                "type": "markdown",
                "title": "Not offered as steps",
                "body": "\n".join(offered) + "\n",
            },
        ],
    }


# -- output --------------------------------------------------------------------------------


def outputs() -> dict[str, Any]:
    ids = step_ids()
    missing = [
        m["id"] for _, m in all_methods() if m["id"] not in names.EXCLUDED and m["id"] not in ids
    ]
    if missing:
        raise SystemExit(f"no step id for {missing[:5]}; run with --new-ids")
    registry = build_registry(ids)
    rows = manifest_rows(registry)
    out: dict[str, Any] = {
        "runtime/registry.json": registry,
        "contracts/operation_manifest.yaml": operation_manifest(rows),
        "contracts/step_ui_manifest.yaml": step_ui_manifest(rows),
        "contracts/artifact_policies.yaml": artifact_policies(rows),
        "contracts/connection_types.yaml": connection_types(),
        "ui/actions/actions.yaml": actions_manifest(rows),
        "ui/pages/api-coverage.yaml": api_coverage_page(registry, rows),
        "ui/pages/report-tables.yaml": report_tables_page(registry),
        "extension.yaml": extension_yaml(rows, registry),
    }
    out.update(api_pages(rows))
    return out


class _Dumper(yaml.SafeDumper):
    pass


def _str(dumper: yaml.SafeDumper, value: str) -> Any:
    style = "|" if "\n" in value else None
    return dumper.represent_scalar("tag:yaml.org,2002:str", value, style=style)


_Dumper.add_representer(str, _str)


def render(path: str, value: Any) -> str:
    if path.endswith(".json"):
        return json.dumps(value, ensure_ascii=False, indent=1, sort_keys=True) + "\n"
    if path == "extension.yaml":
        # The form `flow-steward extensions lock-deps` writes, so it changes nothing.
        return yaml.safe_dump(value, sort_keys=False, allow_unicode=True)
    return HEADER + yaml.dump(value, Dumper=_Dumper, sort_keys=False, allow_unicode=True, width=100)


def main(argv: list[str]) -> int:
    if "--new-ids" in argv:
        ids = step_ids()
        used = set(ids.values()) | {c["operation_id"] for c in composite_specs.COMPOSITES}
        for _, m in all_methods():
            if m["id"] in names.EXCLUDED or m["id"] in ids:
                continue
            sid = new_step_id(names.TITLES[m["id"]][0])
            if sid in used:
                raise SystemExit(f"step id {sid} is taken")
            ids[m["id"]] = sid
            used.add(sid)
        STEP_IDS.write_text(json.dumps(ids, indent=1, sort_keys=True) + "\n", encoding="utf-8")
    rendered = outputs()
    for path, value in rendered.items():
        target = BUNDLE / path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(render(path, value), encoding="utf-8")
    print("generated", len(rendered), "files")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
